import * as React from "react";
import * as TogglePrimitive from "@radix-ui/react-toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { controlIcon, disabled, focusRing } from "@/lib/focus";

/**
 * figma: Toggle (96 variants) and ToggleIcon (120)
 *   Variant   Outline | Ghost
 *   Size      sm (h 28, radius-md) | default (h 32, radius-lg) | large (h 36, radius-lg)
 *   State     Off | On/Hover | Focus | Disabled
 *   Position  Single | Left | Middle | Right (+ Top | Bottom for the icon set)
 *
 * `Position` is handled by ToggleGroup, exactly as in ButtonGroup.
 */
const toggleVariants = cva(
  cn(
    "inline-flex items-center justify-center gap-1 px-2.5 text-sm font-medium whitespace-nowrap transition-all",
    controlIcon,
    focusRing,
    disabled,
    "hover:bg-muted hover:text-muted-foreground",
    "data-[state=on]:bg-accent data-[state=on]:text-accent-foreground"
  ),
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        sm: "h-7 min-w-7 rounded-md text-xs",
        default: "h-8 min-w-8 rounded-lg",
        large: "h-9 min-w-9 rounded-lg",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
);

function Toggle({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> & VariantProps<typeof toggleVariants>) {
  return (
    <TogglePrimitive.Root
      data-slot="toggle"
      className={cn(toggleVariants({ variant, size }), className)}
      {...props}
    />
  );
}

export { Toggle, toggleVariants };
